package blockbranch.cubic;

import java.util.Arrays;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.ChunkPos;
import net.minecraft.world.level.chunk.*;
import net.minecraft.world.level.chunk.storage.*;

/** Native immutable snapshot, partial-work recovery and wide-coordinate checks. */
public final class SparsePostProcessingQualification {
 public static int check(ServerLevel level)throws Exception{
  int checks=0;var pos=new ChunkPos(-21000,27000);var queue=new SparsePostProcessing();
  for(int y:new int[]{ColumnLimits.MIN_Y,-8193,-65,320,8192,ColumnLimits.MAX_Y-1})for(int x:new int[]{0,15})for(int z:new int[]{0,15}){var at=new BlockPos(pos.getMinBlockX()+x,y,pos.getMinBlockZ()+z);int value=SparsePostProcessing.pack(at);require(SparsePostProcessing.unpack(value,pos).equals(at),"Wide Y and chunk-edge packing");queue.add(value);queue.add(value);checks++;}
  int[] expected=queue.snapshot();require(expected.length==24,"Queue deduplication");int[] active=queue.begin();require(Arrays.equals(active,queue.snapshot()),"In-flight snapshot retained");int later=SparsePostProcessing.pack(new BlockPos(pos.getMinBlockX()+2,-300,pos.getMinBlockZ()+3));queue.add(later);queue.finish(false);require(queue.snapshot().length==25,"Failed work and concurrent enqueue retained");queue.begin();queue.add(later);queue.finish(true);require(Arrays.equals(queue.snapshot(),new int[]{later}),"New enqueue during processing survives successful batch");queue.restore(expected);
  for(int[] malformed:new int[][]{new int[]{-1},new int[]{ColumnLimits.HEIGHT<<8},new int[]{SparsePostProcessing.pack(new BlockPos(0,0,0))},new int[]{expected[0],expected[0]},new int[SparsePostProcessing.LIMIT+1]}){boolean rejected=false;try{SparsePostProcessing.validate(malformed);}catch(IllegalArgumentException e){rejected=true;}require(rejected,"Malformed update array rejected");checks++;}
  var budget=new SparsePostProcessing();for(int i=0;i<SparsePostProcessing.LIMIT;i++)budget.add(i);boolean bounded=false;try{budget.add(SparsePostProcessing.LIMIT);}catch(IllegalStateException e){bounded=true;}require(bounded&&budget.snapshot().length==SparsePostProcessing.LIMIT,"Queue capacity fails closed without growth");
  var proto=new ProtoChunk(pos,UpgradeData.EMPTY,level,level.palettedContainerFactory(),null);for(int value:expected)proto.markPosForPostProcessing(SparsePostProcessing.unpack(value,pos));
  require(Arrays.equals(((SparsePostProcessingAccess)proto).blockbranch$postProcessing(false).snapshot(),expected),"Native proto routes out-of-window updates");
  var frozen=SerializableChunkData.copyOf(level,proto);proto.markPosForPostProcessing(SparsePostProcessing.unpack(later,pos));var tag=frozen.write();require(tag.getIntOr("blockbranch:column_format",0)==3,"Pending updates carry downgrade barrier");require(Arrays.equals(tag.getIntArray(SparsePostProcessing.KEY).orElseThrow(),expected),"Native save snapshot immutable");
  try(var oldReader=new java.net.URLClassLoader(new java.net.URL[]{java.nio.file.Path.of(System.getProperty("blockbranch.deepColdPriorJar")).toUri().toURL()},SparsePostProcessingQualification.class.getClassLoader()){@Override protected Class<?> loadClass(String name,boolean resolve)throws ClassNotFoundException{if(!name.equals("blockbranch.mixin.cubic.SerializableChunkDataMixin"))return super.loadClass(name,resolve);synchronized(getClassLoadingLock(name)){var c=findLoadedClass(name);if(c==null)c=findClass(name);if(resolve)resolveClass(c);return c;}}}){var c=oldReader.loadClass("blockbranch.mixin.cubic.SerializableChunkDataMixin");var method=Arrays.stream(c.getDeclaredMethods()).filter(m->m.getName().equals("blockbranch$parse")).findFirst().orElseThrow();method.setAccessible(true);boolean rejected=false;try{method.invoke(null,level,level.palettedContainerFactory(),tag,(com.llamalad7.mixinextras.injector.wrapoperation.Operation<SerializableChunkData>)(args)->{throw new AssertionError("Old reader consumed pending-update save");});}catch(java.lang.reflect.InvocationTargetException e){for(Throwable cause=e.getCause();cause!=null;cause=cause.getCause())if(cause.getMessage()!=null&&cause.getMessage().contains("Unsupported Blockbranch column format"))rejected=true;}require(rejected,"Actual adopted97 chunk reader rejects transient format3 before consuming chunk");}
  var parsed=SerializableChunkData.parse(level,level.palettedContainerFactory(),tag);var restored=parsed.read(level,level.getPoiManager(),new RegionStorageInfo("postprocessing",level.dimension(),"postprocessing"),pos);require(Arrays.equals(((SparsePostProcessingAccess)restored).blockbranch$postProcessing(false).snapshot(),expected),"Native proto save/read retains queue");
  var full=new LevelChunk(level,restored,null);var promoted=((SparsePostProcessingAccess)full).blockbranch$postProcessing(false);require(Arrays.equals(promoted.snapshot(),expected),"Native promotion retains queue");promoted.begin();var inflight=SerializableChunkData.copyOf(level,full).write();require(Arrays.equals(inflight.getIntArray(SparsePostProcessing.KEY).orElseThrow(),expected),"Native in-flight save retains queue");var fullReload=SerializableChunkData.parse(level,level.palettedContainerFactory(),inflight).read(level,level.getPoiManager(),new RegionStorageInfo("postprocessing",level.dimension(),"postprocessing"),pos);require(fullReload instanceof ImposterProtoChunk&&Arrays.equals(((SparsePostProcessingAccess)fullReload).blockbranch$postProcessing(false).snapshot(),expected),"Full saved chunk restores in-flight queue through imposter wrapper");promoted.finish(true);var complete=SerializableChunkData.copyOf(level,full).write();require(complete.getIntOr("blockbranch:column_format",0)==2&&!complete.contains(SparsePostProcessing.KEY),"Completed queue returns to ordinary format");
  for(int kind=0;kind<4;kind++){var bad=tag.copy();if(kind==0)bad.remove(SparsePostProcessing.KEY);else if(kind==1)bad.putInt("blockbranch:column_format",2);else if(kind==2)bad.putIntArray(SparsePostProcessing.KEY,new int[]{expected[0],expected[0]});else bad.putIntArray(SparsePostProcessing.KEY,new int[0]);boolean rejected=false;try{SerializableChunkData.parse(level,level.palettedContainerFactory(),bad);}catch(RuntimeException e){rejected=true;}require(rejected,"Native malformed pending save rejected");checks++;}
  blockbranch.Blockbranch.LOGGER.info("SPARSE_POSTPROCESSING_PASS checks={} immutableSave=true promotion=true recovery=true",checks+14);return checks+14;
 }
 private static void require(boolean ok,String message){if(!ok)throw new AssertionError(message);}
}
